import json,re
worlds=[]
def world(id,title,briefing,signature,entry,sections,transfer,distinct,compare,sources):
 worlds.append(dict(id=id,title=title,briefing=briefing,signature=dict(zip(['truth','traffic','latency','risk','cost'],signature)),entryScenario=entry,sections=[dict(title=t,html=h) for t,h in sections],transfer=transfer,distinct=distinct,compare=[dict(world=w,title=t,html=h) for w,t,h in compare],sources=[dict(title=t,url=u) for t,u in sources]))

world('money','Мир денег: платежи, кошельки и финансовый учёт',
'Знакомая сумма на экране скрывает несколько разных фактов: распоряжение принято, средства заблокированы, расчёт завершён, запись попала в учёт. Этот паспорт помогает отличить быстрый интерфейс от корректного денежного процесса.',
['Подтверждённый денежный факт и история его основания','Точечные записи, запросы статуса, события, реестры и сверка','Раздельные бюджеты приёма и окончательного расчёта','Повторный эффект, пропуск операции, неразрешённая неопределённость','Эксплуатация, надёжность, проверки и обработка спорных операций'],
'Учебный кошелёк должен перевести 1200 рублей со счёта А на счёт Б. Клиент потерял ответ и нажал повтор. Нужна определённость о прежнем действии, а не просто ещё один успешный HTTP-запрос.',[
('Что продаёт бизнес и что считается истиной','''<p>Платёжный сервис продаёт возможность безопасно изменить денежные обязательства и получить достоверное подтверждение. Источник истины зависит от факта. Локальная запись может подтверждать принятие распоряжения, а окончательный расчёт происходит у внешнего участника. Статус «принят» не следует автоматически называть «оплачен». Отдельно определите, какое событие увидит клиент и что сможет доказать поддержка.</p><p>Учётная модель должна сохранять сумму, валюту, идентификатор операции, участников и основание изменения. Двойная запись полезна для сохранения связанной истории дебета и кредита, но сама по себе не исправляет неверные бизнес-правила или повтор внешней команды. Корректность включает контроль допустимых переходов и право на действие. Отчёт по агрегированному балансу не заменяет проверку конкретных проводок.</p>'''),
('Три контура вместо одного success','''<p>Разделите приём намерения, исполнение и наблюдение результата. У операции есть устойчивый business_id и понятная машина состояний. API может быстро подтвердить принятие и позволить получить конечный статус позднее. Если партнёр ответил с задержкой или ответ потерялся, операция становится неопределённой, а не автоматически неуспешной. Поддержка должна видеть причину и следующий шаг.</p><p>Сверка восстанавливает соответствие между надёжными источниками: принятые распоряжения, внешний реестр, учёт. Она проверяет идентификаторы, сумму, валюту, статус и допустимое запаздывание. Равные количества строк не исключают двух пропусков и двух дублей. Неразобранные расхождения получают владельца и срок. Это часть проектирования, а не бесконечная ручная работа после запуска.</p>'''),
('Повторы и транзакционные границы','''<p>Локальная транзакция может атомарно сохранить намерение, изменение счёта и запись outbox в одной БД. Она не включает произвольный HTTP-вызов внешнего провайдера. Если приложение упало после внешнего списания, локальный rollback не отменит внешний факт. Нужны согласованный идемпотентный контракт, поиск по прежнему идентификатору и восстановление состояния.</p><p>Срок действия ключа повторов имеет значение. Если клиент возвращается после двух суток, а провайдер хранит ключ сутки, прежняя защита может уже не действовать. Система должна знать собственный устойчивый результат либо ограничить такой повтор. Число retries и backoff регулируют нагрузку, но не создают бизнес-безопасность. Отдельно испытывают позднее подтверждение, повтор уведомления и конфликт параметров одного ключа.</p>'''),
('Кэш, нагрузка и интерфейсы','''<p>Финтех не означает отсутствие кэша. Справочники, публичные курсы с указанной актуальностью, доступные предложения и части истории могут кэшироваться по согласованному правилу. Решение о доступном остатке для операции требует своей гарантии и источника. Опасно превращать устаревший отображаемый баланс в разрешение нового списания.</p><p>B2C часто добавляет короткие мобильные сессии, повтор после обрыва сети и массовые чтения. B2B может усиливать пакетные реестры, несколько подписантов, расписания и корпоративные права. Это различие сценариев, а не правило «один высоконагруженный, другой нет». В одном продукте могут сосуществовать оба профиля и общая учётная база.</p>'''),
('Что ломается и как выглядит готовность','''<p>Критический тест разрывает ответ после успешного внешнего исполнения. Затем система получает повтор клиента, позднее уведомление и повторный запуск обработчика. Проверяем не только отсутствие ошибки API, но и единственный разрешённый денежный эффект, сохранение истории и достижение определённого состояния. Отдельно проверяем восстановление БД и полномочия на возврат.</p><p>Ноль наблюдавшихся дублей не доказывает нулевую вероятность. Нужны объяснённые механизмы защиты и проверка перечисленной модели отказов. SLO по технической доступности не является бюджетом допустимых неверных списаний. Перенос ответственности на провайдера тоже не делает безопасным локальное обещание клиенту.</p>'''),
('Как переносить опыт в другой бизнес','''<p>Знания о намерении, подтверждении, повторе и сверке пригодятся в бронировании, логистике и управлении устройствами. Но денежный возврат не равен физическому откату: комиссию или уже понесённые расходы может быть нельзя устранить автоматически. При переходе в геосервис сохраните дисциплину состояний и добавьте свежесть координат, пространственный поиск и оптимизацию назначения. Не начинайте изучение новой отрасли с отказа от того, что уже умеете.</p>''')],
['Состояния операции, идентичность повтора и сверка','Локальные инварианты и проверка внешнего эффекта','Отделение технического SLO от корректности бизнеса'],
['Семантика денежного учёта и конечного расчёта','Права на финансовое действие и история оснований'],
[('inventory','Деньги и последний билет','<p>Оба сценария защищают ограниченный ресурс от конкурентного использования. В билете появляется срок резерва, а в оплате — внешний эффект, который может завершиться после потери ответа. Общее слово «транзакция» не делает эти границы одинаковыми.</p>')],
[('ЮKassa: формат взаимодействия и идемпотентность, актуальные условия проверять у провайдера','https://yookassa.ru/developers/using-api/interaction-format'),('PostgreSQL18: изоляция транзакций','https://www.postgresql.org/docs/18/transaction-iso.html')])

world('inventory','Мир ограниченного ресурса: торговля, билеты и бронирование',
'Товар в каталоге, свободный номер и место на мероприятии выглядят доступными тысячам людей одновременно. Бизнес должен превратить просмотр в обязательство, не пообещав один ресурс дважды.',
['Подтверждённый резерв в заданной границе запаса','Чтений много, записи концентрируются на популярных объектах','Разная свежесть витрины и подтверждения резерва','Oversell, истёкший резерв, гонка оплаты и отмены','Ёмкость пиков, хранение каталога, поиск и исполнение заказа'],
'В учебном магазине осталось десять одинаковых комплектов. Акция привела пять тысяч читателей и сто одновременных попыток купить. Нужно различить просмотр, резерв и подтверждённую продажу.',[
('Ресурс и обещание','''<p>Начните с определения границы: остаток товара на конкретном складе, один номер на конкретные даты, место на конкретный сеанс. Количество само по себе недостаточно. Номер свободен на одну ночь и занят на другую; доставка имеет вместимость и временной интервал; товар может быть в продаже, но недоступен для нужного региона.</p><p>Разделите предложение, временный резерв и окончательное подтверждение. Бизнес определяет, допустимо ли принять заявку без гарантированного ресурса и когда пользователь получает обещание. Архитектура затем обеспечивает именно это правило. Если внешняя WMS недоступна, кэш витрины не создаёт права резервировать её запас. Возможен отдельный заранее делегированный пул, но это самостоятельный механизм с правилами возврата.</p>'''),
('Конкуренция вместо простого счётчика','''<p>Чтение count=1 и последующая запись count=0 двумя запросами создают гонку: два клиента могут увидеть один и тот же ресурс. Защита должна объединять проверку и изменение. Например, условное атомарное обновление уменьшает доступность только при достаточном количестве; для другого инварианта нужны блокировка, ограничение или иной протокол. Проверяют результат изменения, а не просто отсутствие исключения.</p><p>Популярный товар создаёт горячую строку или ключ. Дополнительные API-процессы увеличивают конкуренцию, но не делают один неделимый ресурс параллельным. Шардинг по товару тоже не дробит один горячий товар автоматически. Сначала измеряют ожидания и предел операции, затем обсуждают очереди, ограничение входа и изменение представления ресурса. Нельзя распределить один физический комплект между шардами без общей модели.</p>'''),
('Время, резерв и внешний платёж','''<p>Резерв имеет идентификатор, владельца, состояние и срок. Истечение срока должно быть согласовано с подтверждением оплаты. Если оплата успела пройти, а уборщик резервов уже вернул товар, система обязана определить следующий допустимый шаг: восстановить резерв при наличии, компенсировать или передать спор в разбор. Фоновое удаление по TTL не является полной бизнес-машиной состояний.</p><p>Часы и задержки создают пограничные случаи. Время клиентского устройства не должно единолично определять право на ресурс. Запоздавшее событие может описывать платёж, выполненный до истечения. Укажите, какое время и источник являются основанием перехода. Повтор создания резерва с тем же ключом должен вернуть прежний результат, а не занимать ещё один комплект.</p>'''),
('Каталог, поиск и чтение','''<p>Каталог обслуживает описание, изображения, фильтры и предварительную доступность. Для него полезны поисковый индекс, CDN и кэш. Эти производные копии могут иметь допустимый lag. Окончательная цена и резерв подтверждаются по правилу покупки; снимок условий сохраняется в заказе. Изменившийся завтра каталог не должен переписывать вчерашнюю сделку.</p><p>Сезонная акция меняет распределение, а не только общий RPS. Тысяча запросов к разным товарам и тысяча к одному остатку нагружают систему по-разному. В нагрузочном профиле нужны hot set, одновременные корзины, отмены и повторы. При потере кэша оцените поток в источник. Деградация рекомендаций может освободить ресурсы для оформления, если заранее согласована.</p>'''),
('История против состояния','''<p>Пользователю нужно текущее состояние, поддержке — история переходов, аналитике — поток фактов. Они могут использовать разные модели хранения с общей идентичностью операции. Возврат и отмена не удаляют факт продажи из истории; они добавляют новые основания изменения. Внешние складские движения могут приходить поздно и требовать сверки.</p><p>Бронирование гостиницы добавляет интервалы и изменения дат, билет — индивидуальное место, производство — партии и срок годности. Прежде чем переносить решение магазина, выясните математическую модель ресурса. Общая схема «корзина→оплата» скрывает самые важные отличия этих бизнесов.</p>'''),
('Учебная проверка','''<p>Смоделируйте десять комплектов, сто конкурирующих запросов, потерю ответа у двух клиентов и позднюю оплату одного истёкшего резерва. Сверьте активные резервы, подтверждённые продажи и свободный запас. Затем выключите витринный кэш. Корректность должна сохраниться при более медленной или ограниченной выдаче, а не держаться на случайно низкой конкуренции.</p>''')],
['Атомарное изменение ограниченного ресурса','Повторы, состояния и компенсации','Разделение витрины и подтверждённого факта'],
['Срок резерва, интервалы, единицы запаса и физическое исполнение','Горячие объекты и связь оплаты с истечением резерва'],
[('geo','Остаток товара и свободный курьер','<p>Оба ресурса ограничены, но курьер движется, меняет доступность и может отказаться. Резервирование требует свежего наблюдения и протокола подтверждения, а качество назначения оценивается ещё и временем подачи.</p>')],
[('PostgreSQL18: конкурентность и изоляция','https://www.postgresql.org/docs/18/transaction-iso.html'),('OzonTech: буферизация резервирования, публикация2025; исторический пример, не универсальная схема','https://habr.com/ru/companies/ozontech/articles/950044/')])

world('search','Мир выбора: поиск, объявления, реклама и рекомендации',
'Здесь результатом становится не одна найденная строка, а полезный порядок объектов. Быстрый ответ может быть бесполезным, а качественный ответ — слишком дорогим для нужной задержки.',
['Исходный объект плюс версия производного индекса и модели','Много чтений, массовая индексация, ML-признаки и события поведения','Короткий бюджет поиска и отдельно допустимый lag индекса','Пропуск подходящего объекта, устаревшее предложение, ошибочный доступ','Индексирование, память, вычисление ranking, эксперименты и хранение'],
'В каталоге миллионы предложений. Пользователь пишет «тёплая куртка на осень», а SQL-поиск по точному названию не находит нужное. Нужно получить кандидатов, оценить их и не показать уже недоступное.',[
('Поиск — конвейер с разными задачами','''<p>Различайте получение кандидатов и их ранжирование. Первый этап стремится быстро собрать достаточно подходящих объектов; второй выбирает порядок с более дорогими признаками и моделями. Иногда нужен дополнительный переранжирующий этап для разнообразия, бизнес-ограничений или персонализации. Если первый этап потерял хороший объект, модель на последнем его уже не вернёт.</p><p>Для объяснения качества полезны понятия полноты и точности. Высокая полнота сохраняет подходящие результаты, высокая точность уменьшает долю лишних. В реальном продукте добавляются полезность верхних позиций, разнообразие, свежесть и бизнес-результат. Одна метрика клика может поощрять привлекательные, но бесполезные предложения. Согласуйте, какой эффект действительно нужен пользователю.</p>'''),
('Индекс и источник','''<p>Инвертированный индекс связывает термины с документами и позволяет быстро отобрать объекты по словам. Полнотекстовый поиск требует обработки языка, форм слов и опечаток. Векторный поиск помогает искать по сходству представлений, но не гарантирует выполнения точных условий. Гибрид сочетает сигналы, после чего всё равно нужны фильтры прав, региона, цены и доступности.</p><p>Поисковая копия отделена от источника истины. Обновление объявления может ещё не попасть в индекс; удаление и изменение прав тоже требуют доставки. Укажите версию и допустимый возраст, наблюдайте отставание. Перестроение индекса должно иметь маршрут проверки и переключения: существующие запросы не обязаны ждать окончания полного rebuild.</p>'''),
('Разные бизнесы используют похожую воронку','''<p>У объявлений важны актуальность, география и модерация; у товарного поиска — свойства и наличие; у найма — совместимость требований и кандидата; у рекламы — ограничения кампании, бюджет и полезность показа. Общий паттерн candidate retrieval→ranking переносится, но целевая функция и допустимые последствия ошибки меняются.</p><p>Рекомендации могут начинаться без явного поискового запроса. Сигналами служат история и контекст, а для новых пользователей возникает cold start. Нельзя считать, что наличие большой истории автоматически улучшает качество: данные могут отражать старые правила показа и смещения. Эксперимент должен сравнивать сопоставимые группы и учитывать долгосрочный эффект.</p>'''),
('ML внутри бюджета задержки','''<p>Расчёт сотен дорогих признаков для миллиона объектов не поместится в короткий ответ. Многоступенчатая воронка уменьшает множество на каждом этапе: дорогой скорер работает с меньшим числом кандидатов. Некоторые признаки рассчитываются заранее, другие — онлайн. Предрасчёт ускоряет ответ ценой свежести и поддержки pipeline.</p><p>Локальный успех модели на отложенном наборе не гарантирует production-эффект. Проверьте совместимость признаков, версию модели, задержку serving, поведение при отсутствии признака и качество по сегментам. Ошибка общего feature-сервиса может ухудшить несколько продуктов одновременно. Fallback должен выдавать допустимый результат, пусть и менее персонализированный.</p>'''),
('Наблюдать полезность, а не только p99','''<p>Измеряйте задержку этапов, пустые выдачи, отставание индекса, отсутствие признаков и нарушения фильтров. Добавьте продуктовую проверку на понятных сценариях. Ускоренный поиск, который игнорирует обязательный регион, не является улучшением. Отдельно проверьте документы разных организаций: найденный закрытый объект нельзя просто спрятать после передачи его генеративной модели.</p><p>Для публикаций реальных компаний фиксируйте дату. Разбор AvitoTech от30сентября2024года показывает этапность поиска и ранжирования, но не является обещанием, что весь текущий стек компании совпадает с нарисованной схемой. В курсе используется логика задач и решений, а не выдуманная реконструкция чужого production.</p>'''),
('Мост к генеративному поиску','''<p>RAG добавляет генерацию поверх найденного контекста. Он наследует проблемы полноты, актуальности и прав поиска, затем добавляет собственные риски ответа. Если retrieval не получил нужный регламент, сильная модель может лишь убедительнее заполнить пробел. Проверяйте поиск и объяснение отдельно. Наличие ссылки в ответе полезно только когда она действительно подтверждает утверждение и доступна этому пользователю.</p>''')],
['Индексация, производные модели чтения и lag','Версионирование pipeline и испытание отказов','Раздельные показатели технического и бизнес-качества'],
['Candidate retrieval и многоэтапный ranking','ML-признаки, cold start и оценка качества выдачи'],
[('money','Поиск товара и проверка платежа','<p>Поиск допускает несколько полезных вариантов ранжирования. У факта списания не должно быть «примерно релевантного» ответа. Генеративное объяснение может помогать поддержке, но факт операции по-прежнему определяется надёжным источником.</p>')],
[('AvitoTech: поисковое ранжирование,30.09.2024','https://habr.com/ru/companies/avito/articles/846832/'),('Elasticsearch: инвертированный индекс и базовые понятия','https://www.elastic.co/docs/solutions/search')])

world('geo','Мир движения: карты, такси и назначение исполнителей',
'На карте можно нарисовать точку, но для полезного назначения нужно знать, где объект был, насколько свежо наблюдение, может ли он выполнить заказ и когда действительно приедет.',
['Положение с временем наблюдения и подтверждённое назначение','Поток координат, геопоиск, маршрутизация, события заказа','Свежесть позиции, время ответа и качество ETA — разные ограничения','Устаревшее назначение, двойной исполнитель, невыполнимый маршрут','Обновления индексов, расчёт маршрутов, модели и связь с устройствами'],
'В городе три свободных курьера. Ближайший по прямой находится за рекой без удобного переезда, другой только что потерял связь, третий может приехать быстрее по дороге. Как выбрать?',[
('Разделить пространственный поиск и маршрут','''<p>Геоиндекс быстро сокращает кандидатов по области и пространственному отношению. Это не готовый ответ о времени поездки. Расстояние по прямой и длина маршрута различаются; дорожный граф учитывает соединения, направления и другие ограничения. ETA — оценка времени прибытия при текущих условиях и неопределённости, а не просто километры, делённые на константу.</p><p>Карты, такси и логистика используют общие данные, но решают разные задачи. Карта должна хранить и показывать пространственные объекты; навигация строит путь; такси назначает доступного исполнителя; планирование доставок распределяет множество остановок с временными и ресурсными ограничениями. Один универсальный «геосервис» скрывает различия этих функций.</p>'''),
('Координата — наблюдение, а не вечная истина','''<p>Храните вместе с позицией время измерения, время получения, точность и источник. Устройство может отправить накопленные точки после восстановления сети. Если сортировать только по поступлению, старое измерение перезапишет новое и машина «вернётся» в прежнее место. Порядок и идентичность событий должны учитывать протокол устройства.</p><p>Для свежего поиска нужен небольшой рабочий набор последних допустимых наблюдений, а для аналитики — история перемещения. Они имеют разные access patterns и сроки хранения. Подпись «курьер рядом» требует политики допустимого возраста. Нельзя молча компенсировать неизвестную позицию тем, что в базе осталась старая точка. Модель должна уметь сказать «местоположение устарело».</p>'''),
('Назначение — конкурентный протокол','''<p>Несколько заказов могут одновременно выбрать одного курьера. Поэтому выбор кандидата и подтверждённое назначение различаются. Есть предложение, срок ожидания, принятие или отказ и защита от несовместимых назначений. Временная аренда права может истечь, пока исполнитель отвечает. Позднее принятие проверяется по актуальному идентификатору предложения, а не автоматически меняет заказ.</p><p>Жадное назначение ближайшего кандидата может быть хорошим простым стартом, но не минимизировать общий простой всех участников. Пакетное matching сопоставляет несколько заказов и исполнителей с общей целевой функцией, добавляя ожидание и вычисления. Качество оценивается не только скоростью алгоритма: важны подача, отмены, загрузка и достижимое число выполненных заказов.</p>'''),
('Регионы и неравномерность','''<p>Городское распределение очень неоднородно. Вокзал после концерта и тихий пригород имеют разный спрос, скорость обновлений и число кандидатов. Разбиение по географическим ячейкам удобно, пока пограничные запросы и горячие зоны не становятся главной проблемой. Индекс должен учитывать соседние области, иначе ближайший исполнитель за границей ячейки пропадёт.</p><p>Перераспределение регионов меняет владельца данных и вычислений. В момент переключения важно не потерять позицию и не создать два центра назначения. Здесь знакомые fencing и единственный владелец записи соединяются со свежестью и пространственной локальностью. Не требуется одинаково сильная согласованность всей истории трека и критического права на назначение.</p>'''),
('Проверка качества','''<p>Сценарий испытания включает быстро движущийся объект, запоздавший пакет точек, обрыв связи, два конкурирующих заказа и отказ сервиса маршрутов. Считайте возраст позиции, точность ETA по сегментам, процент невыполнимых назначений и время перехода к следующему кандидату. Низкий p99 геопоиска не спасает от систематически неверной подачи.</p><p>Опубликованный в2019году разбор Яндекс.Такси полезен как сравнение жадного подхода и более общего назначения. Мы используем объяснённые там задачи как исторический источник насмотренности, а вымышленный проект строим со своими условиями. Не переносим чужие числа и не обещаем воспроизвести текущую архитектуру компании.</p>'''),
('Переход из финансовых систем','''<p>Сохраните дисциплину состояний, повторов, подтверждения и аудита. Добавьте пространственную модель, возраст наблюдения, оптимизацию общего распределения и связь с физическим исполнителем. В отличие от проводки, координата допустимо устаревает и уточняется; в отличие от предварительной точки, подтверждённое назначение создаёт обязательство. Это различие позволяет выбрать отдельные гарантии для каждого факта.</p>''')],
['Состояния, подтверждение и идемпотентность назначения','Владение данными и безопасное переключение','Сверка цифрового состояния с внешним фактом'],
['Геоиндекс, дорожный граф, ETA и пространственные границы','Возраст наблюдений и оптимизация matching'],
[('telemetry','Курьер и промышленный датчик','<p>Оба присылают наблюдения с временем и возможным запаздыванием. Курьер дополнительно участвует в назначении и может отказаться, а датчик может потребовать локального управления при разрыве связи. Поток измерений не следует считать доказательством исполнения команды.</p>')],
[('PostGIS: пространственные запросы','https://postgis.net/docs/using_postgis_query.html'),('Яндекс: распределение заказов,07.02.2019; исторический кейс','https://habr.com/ru/companies/yandex/articles/439182/')])

world('collaboration','Мир общего состояния: чаты, документы и игры',
'Пользователи видят один разговор или документ с разных устройств, иногда offline. Система должна объяснить порядок, доставку и результат одновременных действий, а не только держать открытый сокет.',
['Сохранённое сообщение или допустимо объединённое изменение','Долгоживущие соединения, fan-out и синхронизация после offline','Ответ интерфейса, доставка, прочтение и синхронизация различаются','Потери, дубли, конфликт изменений, неверные права','Число соединений, распространение, история и хранение вложений'],
'Два диспетчера редактируют один маршрутный документ; один потерял сеть. Параллельно клиент отправляет сообщение с телефона и затем открывает ноутбук. Что именно должно сойтись?',[
('Соединение и состояние не одно и то же','''<p>WebSocket обеспечивает двусторонний обмен поверх соединения, SSE удобен для потока сервера к клиенту, polling может быть приемлем при редком изменении. Выбор транспорта не определяет хранение истории, права, идемпотентность и семантику подтверждения. После разрыва нужен протокол получения пропущенного, а не вера в «реальное время».</p><p>У сообщения есть клиентский идентификатор, сохранённый серверный факт и отдельные подтверждения. «Отправлено», «доставлено устройству» и «прочитано человеком» — разные события с разной доказуемостью. Одно устройство пользователя может быть онлайн, другое — нет. Модель должна определять, какое наблюдение соответствует каждой отметке интерфейса.</p>'''),
('Порядок и fan-out','''<p>Нельзя автоматически обещать единый глобальный порядок всех разговоров. Часто достаточно порядка внутри диалога или версии документа. Сервер может присваивать последовательность после приёма; клиентский timestamp сам по себе ненадёжен из-за разных часов и offline. Повтор с прежним message_id не должен создавать новое сообщение.</p><p>Fan-out — распространение одного события многим получателям. Можно готовить персональные потоки при записи либо собирать их при чтении; есть и гибрид. Большая публичная группа, приватный диалог и уведомление сотрудникам компании имеют разную стоимость распространения. Расчёт «RPS сообщений» без числа адресатов скрывает главный множитель нагрузки.</p>'''),
('Одновременное редактирование','''<p>Замена всего документа последней записью проста, но может стереть чужую работу. Optimistic concurrency проверяет версию и требует разрешить конфликт. Operational Transformation и CRDT задают другие модели совместного изменения. Они требуют понимания операций, доставки, идентичности и истории; это не настройка WebSocket.</p><p>CRDT может обеспечить сходимость поддерживаемых операций при выполнении предпосылок, но не гарантирует, что итог выражает бизнес-намерение. Два редактора могут согласованно получить документ с двумя несовместимыми назначениями. Критические доменные правила всё равно нуждаются в отдельной проверке. Библиотека синхронизации текста не превращается автоматически в систему финансового учёта.</p>'''),
('Offline и права','''<p>Клиент хранит локальные изменения и курсор синхронизации. После подключения он отправляет повторяемые операции и получает историю после известной позиции. Ограничьте объём восстановления, обработайте удаление объекта и изменение доступа. Если пользователь лишился прав во время offline, его старое разрешение не должно автоматически давать право применить новые изменения.</p><p>Присутствие «онлайн» обычно является временным наблюдением, а не вечным фактом. Оно может исчезать по тайм-ауту или иметь задержку; ошибка presence не должна повреждать сохранённые сообщения. Разделяйте эфемерные сигналы набора текста и долговечную историю. Для них нужны разные гарантии и хранение.</p>'''),
('Почему игры выделяются внутри этого мира','''<p>Многопользовательская игра тоже синхронизирует состояние, но может иметь авторитетный серверный шаг, строгий бюджет задержки и компенсацию сетевых расхождений. Нельзя свободно принять любое позднее действие как редактуру документа. История, физика, защита от нечестного клиента и допустимость исправления экрана задают другие ограничения.</p><p>Matchmaking игры отличается от назначения курьера целевой функцией: подходят ли игроки по навыку, региону и ожиданию. Общий паттерн подбора ограниченного набора переносится, но качество и границы отказа меняются. В курсе это сравнительная экспедиция, а не обязательное создание собственного игрового движка.</p>'''),
('Проверка без магии realtime','''<p>Проверьте повтор отправки, перезагрузку клиента, разрыв после сохранения, изменение прав и два параллельных изменения. Затем восстановите состояние на новом устройстве. Результат должен объясняться протоколом и версиями, а не только визуально «работать в двух вкладках». Отдельно измерьте задержку распространения и объём истории, необходимый для возврата после долгого offline.</p>''')],
['Идентификаторы операций, повторы и курсоры истории','События, хранение и границы доступа','Раздельные гарантии факта и наблюдения'],
['Fan-out, долгоживущие соединения и offline-синхронизация','Модели конкурентного редактирования и смысл сходимости'],
[('geo','Общий документ и назначение курьера','<p>Согласованно объединить текстовые изменения бывает допустимо. Два назначения одного курьера нельзя исправить одним слиянием строк: нужен бизнес-инвариант и подтверждённое владение ресурсом. Одинаковый realtime-транспорт не делает модели состояния одинаковыми.</p>')],
[('RFC6455: WebSocket','https://www.rfc-editor.org/rfc/rfc6455'),('Yjs: shared data types и CRDT, актуальные ограничения проверять по библиотеке','https://docs.yjs.dev/')])

world('media','Мир больших потоков: видео, музыка и трансляции',
'Миллион зрителей не означает миллион одинаковых транзакций. Главными становятся объём передаваемых данных, подготовка контента, близость копии и качество воспроизведения.',
['Исходный объект, проверенные производные версии и права просмотра','Крупные загрузки, обработка, многократная доставка сегментов','Время старта, остановки воспроизведения и задержка live','Потеря исходника, неполная обработка, массовый cache miss','Хранение, сетевой трафик, транскодирование и геораспределённая ёмкость'],
'Компания разрешила продавцам прикреплять видео товара. Файлы загружаются с мобильной сети, часть загрузок обрывается, зрители используют разные скорости связи. Одной колонки video_blob уже недостаточно.',[
('Объект, метаданные и производные','''<p>Разделите бинарный объект и метаданные: владелец, версия, размер, checksum, права, статус обработки. Объектное хранилище удобно для больших неизменяемых объектов; транзакционная база хранит связанное описание. Между ними нет общей транзакции по умолчанию. Поэтому статус «готов» должен появляться после проверки существования и допустимости нужных версий.</p><p>Исходник и производные имеют разную ценность. Потерянную уменьшенную картинку можно восстановить, если исходник сохранён и pipeline воспроизводим. Удаление оригинала ради экономии меняет возможность повторной обработки. Срок хранения и права должны охватывать копии, thumbnails, CDN и резервные данные, а не только запись каталога.</p>'''),
('Загрузка при плохой сети','''<p>Большой файл нельзя заставлять начинать заново при каждом обрыве. Протокол порционной загрузки фиксирует идентификатор сессии, части и условие завершения. Нужны срок жизни незавершённых частей, проверка размера и контроль целостности. URL для загрузки должен иметь ограниченные права и срок, а не открывать произвольную запись в хранилище.</p><p>Завершение приёма не означает готовность к показу. Проверка безопасности, извлечение метаданных и подготовка форматов идут отдельно. Если один этап падает, задача должна повторяться без создания новых неконтролируемых объектов. Ограничивайте очередь и ресурсы обработки, чтобы загрузки не вытеснили критический путь заказов.</p>'''),
('Подготовить контент под клиента','''<p>Разные разрешения и битрейты позволяют адаптировать воспроизведение к устройству и сети. Транскодирование создаёт несколько производных вариантов; упаковка разбивает поток на доступные клиенту части и описывает их. HLS — один из протоколов такой доставки, но наличие плейлиста не гарантирует правильной настройки всего pipeline.</p><p>Клиент выбирает допустимое качество по доступной скорости и состоянию буфера. Маленькие сегменты могут уменьшить часть задержки ценой большего числа запросов и накладных расходов; детали зависят от протокола и режима. Для live контент ещё появляется, поэтому время публикации, окно хранения и задержка до зрителя требуют отдельного проектирования.</p>'''),
('CDN и origin','''<p>CDN распространяет копии ближе к пользователям и уменьшает обращения к исходному origin. Считайте байты и распределение популярности: один популярный фильм и множество уникальных приватных файлов имеют разный cache hit rate. Ключи и правила доступа должны не допустить выдачу приватного контента через общий кэш.</p><p>Потеря CDN-кэша может вернуть большой поток к origin. Нужны ёмкость, объединение одинаковых запросов, ограничение входа и постепенный прогрев. Географическая распределённость доставки не означает, что исходник и метаданные автоматически отказоустойчивы. Проверяйте цепочку от права пользователя до конкретного сегмента.</p>'''),
('Наблюдаемость со стороны зрителя','''<p>Сервер может успешно отдать все HTTP-ответы, а пользователь всё равно ждёт первого кадра или видит остановки. Метрики качества включают время старта, долю неудачных запусков, rebuffering и выбранное качество. Наблюдение должно учитывать клиентскую сеть и устройство. Один средний bitrate не описывает полезный опыт всех сегментов.</p><p>В учебном расчёте тысяча одновременных зрителей по3Мбит/с потребует около3Гбит/с полезного потока без накладных расходов. Это другая модель ёмкости, чем тысяча запросов к небольшой JSON-ручке. Не путайте мегабиты и мегабайты, пиковую скорость и месячный объём. Финансовая модель должна отдельно учитывать обработку и доставку.</p>'''),
('Отрасли на той же основе','''<p>Онлайн-кинотеатр, обучающие вебинары, телемедицинская видеосвязь и пользовательские ролики разделяют часть механизмов, но live-конференция добавляет двустороннюю коммуникацию, интерактивность и иной бюджет задержки. Поэтому предзаписанный курс через CDN нельзя без анализа объявить готовой платформой звонков. Кейс VK Видео используется как датированное свидетельство полного пути контента, не как универсальная инструкция.</p>''')],
['Асинхронный pipeline, идемпотентность и версии','Права, жизненный цикл данных и отказ зависимостей','Кэш и защита источника при массовом промахе'],
['Байты, bitrate, кодирование, сегменты и CDN','Клиентские метрики воспроизведения и особая семантика live'],
[('search','Медиа и поиск','<p>У обоих есть исходные данные и производные копии. Перестроение индекса похоже на повторную обработку видео по необходимости версий и безопасного переключения, но поисковый запрос расходует вычисления и память, а доставка видео — прежде всего поток байтов и сеть.</p>')],
[('RFC8216: HLS, informational specification2017; не описание всех современных расширений','https://www.rfc-editor.org/rfc/rfc8216'),('VK: путь видео от загрузки до кадра, публикация2026','https://habr.com/ru/companies/vk/articles/1000000/')])

world('telemetry','Мир наблюдений: устройства, промышленность и потоки событий',
'Датчик сообщает, что произошло в физическом мире, иногда позже и несколько раз. Надёжная обработка должна сохранить смысл времени и не принять получение команды за её исполнение.',
['Измерение с идентичностью, временем и происхождением','Много последовательных событий, всплески после offline','Возраст измерения, задержка тревоги и доступность локального управления','Потери, дубли, неверный порядок, опасное действие по старому сигналу','Приём потока, хранение временных рядов, связь и парк устройств'],
'Холодильный склад передаёт температуру. Устройство20минут было offline, затем отправило накопленные измерения. Система получила старое превышение порога после нового нормального значения. Как объяснить историю и текущую тревогу?',[
('Наблюдение и три времени','''<p>Разделяйте event time — когда явление измерено, ingestion time — когда запись принята, и processing time — когда обработана. Эти значения отвечают на разные вопросы. Текущий экран может показывать последнее достоверное измерение, аналитика — строить историю по времени явления. Сортировка по времени приёма создаст неверную картину после offline.</p><p>Часы устройства могут ошибаться. Сохраняйте источник, качество времени, последовательность и признаки точности. Не каждое расхождение можно исправить серверной датой: тогда потеряется смысл того, что измерялось до восстановления связи. Политика поздних данных должна явно определять, когда пересчитываем окно и как исправляем уже опубликованный результат.</p>'''),
('Протокол не равен end-to-end гарантии','''<p>MQTT использует publish/subscribe и имеет уровни доставки в своих протокольных границах. Даже гарантия протокола не делает однократным весь внешний бизнес-эффект: обработчик мог записать тревогу и упасть до своего подтверждения. Идентификатор измерения, повторная обработка и атомарность локального изменения остаются задачами приложения.</p><p>Для устройства нужны регистрация, ограниченные учётные данные, обновление и отзыв доступа. Общий секрет всего парка повышает радиус компрометации. Подписка на тему должна соответствовать правам конкретного устройства или организации. Устройства часто обновляются медленнее серверов, поэтому совместимость формата и длительное сосуществование версий особенно важны.</p>'''),
('Поток и временные ряды','''<p>Хранилище выбирают по access patterns: последние значения, диапазон времени, агрегаты за час, поиск аномалий и долговременный архив. Одна строка «текущее состояние» не заменяет историю, а бесконечная история в транзакционной таблице может быть дорогой для всех задач. Retention, сжатие и понижение детализации зависят от смысла данных и требований.</p><p>Потоковый обработчик объединяет события в окна и поддерживает состояние. Watermark — механизм оценки продвижения event time, а не доказательство, что поздних данных больше никогда не будет. Определите допустимое опоздание и корректирующие результаты. Если тревога влияет на действие, правила отмены и пересмотра тоже должны быть видимыми оператору.</p>'''),
('Edge и команды','''<p>Edge-обработка переносит часть вычислений ближе к устройству. Это может уменьшить задержку и сохранить ограниченную автономность при потере сети, но добавляет управление версиями, локальное состояние и восстановление синхронизации. Облачная платформа не должна быть единственным неиспытанным условием безопасности физического процесса.</p><p>Команда «установить режим» имеет идентификатор, параметры, срок применимости и подтверждение результата. Получение MQTT-сообщения не доказывает, что исполнитель изменил физическое состояние. Нужны отдельный наблюдаемый результат, обработка повторов и запрет просроченных команд. Дальнейшие требования к безопасности конкретного оборудования определяются профильными специалистами; учебный пример не является инструкцией управления производством.</p>'''),
('Ёмкость и восстановление','''<p>После массового восстановления связи устройства могут одновременно выгрузить backlog. Профиль приёма отличается от ровного среднего потока. Ограничьте конкуренцию, распределите повторы и оцените catch-up по разности обработки и входа. Если обработка3000событий/с, а новые измерения приходят2500/с, на сокращение хвоста остаётся500/с, а не3000.</p><p>Метрики включают возраст последних измерений, долю пропусков, лаг, распределение версий устройств и подтверждённые действия. Низкий CPU при пустой очереди может означать, что устройства вообще перестали присылать данные. Для наблюдений отсутствие события само является возможным сигналом, если согласована частота и условия связи.</p>'''),
('Что узнаёт специалист из другой отрасли','''<p>Финтех приносит идентичность, сверку и осторожность с повтором. Медиа — понимание потока и ограниченной связи. Новыми становятся качество физических наблюдений, время события, парк устройств и разделение команды от исполнения. Логистика использует ту же дисциплину для трекеров и сканеров: цифровая отметка должна иметь происхождение, а физическая доставка — отдельное подтверждение.</p>''')],
['Очереди, повторы, версии и ограничения входа','История, восстановление и сверка источников','Права на действия и область внешнего эффекта'],
['Event time, поздние данные и качество часов','Устройства, edge и доказательство физического исполнения'],
[('money','Тревога и платёж','<p>Позднее подтверждение нельзя считать новой операцией только из-за времени приёма. У платежа критичны сумма и единственный эффект, у датчика — время и качество наблюдения. В обоих случаях полезно сохранять происхождение и отдельно разрешать неопределённость.</p>')],
[('OASIS MQTT5.0, стандарт2019','https://docs.oasis-open.org/mqtt/mqtt/v5.0/mqtt-v5.0.html'),('Apache Flink: event time и watermarks','https://nightlies.apache.org/flink/flink-docs-stable/docs/concepts/time/')])

world('saas','Мир организаций: корпоративный SaaS, документы и процессы',
'В одной платформе работают разные компании, каждая со своими людьми, настройками и данными. Пользовательская функция должна оставаться изолированной, даже когда один клиент значительно крупнее остальных.',
['Документ или операция в контексте конкретной организации и версии процесса','Интерактивные CRUD-операции, поиск, экспорты, фоновые задания','Отклик интерфейса и срок завершения процесса различаются','Утечка между клиентами, неверные полномочия, noisy neighbor','Общие ресурсы, сопровождение конфигураций и вариативность клиентов'],
'Две организации ведут заявки в одном сервисе. КлиентА запускает миллионный экспорт, клиентБ пытается открыть свой документ. Одновременно сотрудник меняет роль, а его вчерашний токен ещё действует.',[
('Tenant — граница, а не параметр формы','''<p>Tenant обозначает организационный контекст, который система использует для изоляции данных и ресурсов. Пользователь может работать в нескольких организациях с разными правами. Переданный с клиента tenant_id нельзя считать разрешением сам по себе: сервер устанавливает допустимый контекст из проверенной идентичности и полномочий.</p><p>Проверка должна сохраняться в REST, экспорте, поиске, кэше, фоновой задаче, вложении и аналитике. Удалённая из основного ответа строка не решает проблему, если её содержание уже попало в общий поисковый индекс или AI-контекст. На архитектурной схеме полезно нарисовать все копии и пути чтения, а не одну центральную БД.</p>'''),
('Три модели размещения','''<p>Можно разделять клиентов по отдельным БД, схемам либо строкам общей модели. Каждая стратегия имеет цену в эксплуатации, миграциях, восстановлении и изоляции. Общая таблица упрощает массовое обновление, но требует систематического контроля контекста. Отдельная БД помогает некоторым требованиям изоляции, но не даёт бесплатного сопровождения тысяч клиентов.</p><p>RLS PostgreSQL может ограничивать видимость строк, но нужно понимать роли, владельца таблицы и условия обхода. Это один барьер, а не полная модель безопасности приложения. Пулы соединений должны корректно задавать и очищать контекст; иначе запрос следующего клиента может унаследовать чужое состояние. Проверяйте реальный режим подключения, а не только SQL из презентации.</p>'''),
('Процессы и версии правил','''<p>Корпоративная заявка может жить недели, иметь несколько согласований и менять исполнителей. Сохраняйте версию процесса и основания решения: новое правило не всегда должно переписать уже начатую заявку. Документ, действие над ним и факт подписи имеют разные статусы. Правовые свойства подписей и хранения определяются по применимому режиму с ответственными специалистами.</p><p>Настраиваемость повышает ценность SaaS и усложняет состояние системы. Разные поля, маршруты и интеграции создают комбинации, которые нельзя полностью проверить одним happy path. Ограничивайте поддерживаемые возможности, версионируйте конфигурацию и давайте безопасные проверки до публикации. Ошибка клиентской настройки должна иметь понятную диагностику.</p>'''),
('Крупный клиент и общая очередь','''<p>Noisy neighbor возникает, когда один потребитель ухудшает сервис другим через общий ресурс. Миллионный экспорт может занять пул БД или фоновые workers. Помогают квоты, раздельные очереди, fair scheduling, ограничения запросов и выделенные ресурсы по договору. Простое увеличение общего пула может лишь перенести насыщение в БД.</p><p>Лимит по IP не заменяет лимит по организации и типу операции. У одного офиса общий адрес, а один клиент может распределить работу по многим адресам. Экспорт нужно оценивать отдельно от открытия документа: размер результата, длительность и стоимость различаются. У задания есть владелец, статус, отмена и срок хранения результата.</p>'''),
('Эксплуатация отдельного клиента','''<p>Запрос «восстановить данные организацииА на вчера» сложнее, чем восстановление всего общего кластера. Нужны правила точечного восстановления и согласование с данными, изменившимися после точки. Удаление клиента также охватывает индексы, файлы, события и бэкапы по установленной политике. Одно DELETE не описывает жизненный цикл.</p><p>Observability требует tenant-контекста для расследования, но не должна раскрывать чувствительные данные в общих логах. План поддержки включает персональные доступы, аудит, аварийное расширение полномочий и отзыв. Рост числа клиентов меняет не только RPS, но и объём конфигураций, миграций и операционных действий.</p>'''),
('Разные отрасли на общей основе','''<p>CRM, документооборот, управление образованием и часть медицинских процессов разделяют платформенные механизмы организаций, документов и workflow. Но конкретные данные, интеграции и последствия ошибок различаются. Учёт посещаемости и медицинское изображение нельзя считать эквивалентными записями только потому, что оба имеют owner_id. Сначала выделяйте тип полезного действия, затем применяйте общий паттерн с проверкой границ.</p>''')],
['Права на объект, версии и аудит','Контракты, длинные процессы и асинхронные задания','Измерение качества по пользовательскому пути'],
['Модель tenant-изоляции и вариативность конфигураций','Noisy neighbor, восстановление и жизненный цикл отдельного клиента'],
[('search','Корпоративный поиск','<p>Поисковая система SaaS наследует весь конвейер retrieval/ranking и добавляет обязательную tenant-изоляцию. Хорошее ранжирование чужих документов является нарушением, а не полезной находкой. Права должны действовать до передачи контекста модели.</p>')],
[('PostgreSQL18: Row Security Policies и ограничения ролей','https://www.postgresql.org/docs/18/ddl-rowsecurity.html'),('OWASP API Security2023: объектные и полевые права','https://owasp.org/API-Security/editions/2023/en/0x11-t10/')])

