def editorial(value):
 if isinstance(value,list):return [editorial(x) for x in value]
 if isinstance(value,dict):return {k:editorial(v) for k,v in value.items()}
 if not isinstance(value,str) or value.startswith('https://'):return value
 value=re.sub(r'(?<=[А-Яа-яЁё])(?=[0-9A-Za-z])|(?<=[0-9A-Za-z])(?=[А-Яа-яЁё])',' ',value)
 return value
